function fromBase64Url(b64url) {
  const padded = b64url.replace(/-/g, '+').replace(/_/g, '/');
  const padLen = (4 - padded.length % 4) % 4;
  return atob(padded + '='.repeat(padLen));
}

function fail(code, message) {
  return [{ json: { _statusCode: code, error: message, tokenB64: '' } }];
}

const inputJson = $input.first().json;
const body = inputJson.body || inputJson;
const token = body.token;
const result = body.result;

if (!token || typeof token !== 'string') return fail(400, 'missing token');
if (!result || typeof result !== 'object') return fail(400, 'missing result');

const dotIdx = token.lastIndexOf('.');
if (dotIdx < 1) return fail(401, 'malformed token');
const tokenB64 = token.slice(0, dotIdx);
const sig = token.slice(dotIdx + 1);

let payload;
try {
  payload = JSON.parse(fromBase64Url(tokenB64));
} catch (e) {
  return fail(401, 'invalid payload');
}

const recordId = payload.r;
const expiresAt = payload.e;

if (!recordId || typeof recordId !== 'string' || !recordId.startsWith('rec')) {
  return fail(401, 'invalid recordId in token');
}
if (typeof expiresAt !== 'number') {
  return fail(401, 'invalid expiresAt in token');
}

return [{ json: { _statusCode: 200, tokenB64: tokenB64, sig: sig, recordId: recordId, expiresAt: expiresAt, result: result } }];

const item = $input.first().json;

// Propagate parse failures
if (item._statusCode !== 200) {
  return [{ json: item }];
}

const { tokenB64, sig, expectedSig, recordId, expiresAt, result } = item;

// Constant-time string comparison
if (typeof sig !== 'string' || typeof expectedSig !== 'string' || sig.length !== expectedSig.length) {
  return [{ json: { _statusCode: 401, error: 'invalid signature', recordId: recordId } }];
}
let diff = 0;
for (let i = 0; i < sig.length; i++) diff |= sig.charCodeAt(i) ^ expectedSig.charCodeAt(i);
if (diff !== 0) {
  return [{ json: { _statusCode: 401, error: 'invalid signature', recordId: recordId } }];
}

const now = Math.floor(Date.now() / 1000);
if (now > expiresAt) {
  return [{ json: { _statusCode: 410, error: 'token expired', recordId: recordId } }];
}

// Plausibility checks — reject obviously cheated/scripted results
const issues = [];
const td = result.testDuration;
if (typeof td !== 'number' || td < 55) issues.push('testDuration ' + td);

let charTotal = 0;
if (Array.isArray(result.charStats)) {
  charTotal = result.charStats.reduce(function(a, b) { return a + (typeof b === 'number' ? b : 0); }, 0);
}
if (charTotal < 150) issues.push('charTotal ' + charTotal);

if (typeof result.wpm !== 'number' || result.wpm > 200) issues.push('wpm ' + result.wpm);
if (typeof result.afkDuration !== 'number' || result.afkDuration >= 10) issues.push('afkDuration ' + result.afkDuration);
if (typeof result.restartCount !== 'number' || result.restartCount > 3) issues.push('restartCount ' + result.restartCount);

if (Array.isArray(result.keySpacing) && result.keySpacing.length > 5) {
  const ks = result.keySpacing;
  const mean = ks.reduce(function(a, b) { return a + b; }, 0) / ks.length;
  const variance = ks.reduce(function(a, b) { return a + (b - mean) * (b - mean); }, 0) / ks.length;
  if (variance < 1) issues.push('keySpacing variance ' + variance.toFixed(2));
}

if (issues.length > 0) {
  return [{ json: { _statusCode: 422, error: 'plausibility: ' + issues.join('; '), recordId: recordId } }];
}

const wpm = Math.round(result.wpm * 10) / 10;
const acc = typeof result.acc === 'number' ? result.acc : 0;
// Airtable percent field stores 0-1 (0.95 = 95%)
const accuracy = Math.round((acc / 100) * 1000) / 1000;

// Date-only (YYYY-MM-DD) in Manila timezone — Airtable date field rejects ISO datetime strings
const submittedAt = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Manila',
  year: 'numeric', month: '2-digit', day: '2-digit'
}).format(new Date());

return [{ json: { _statusCode: 200, recordId: recordId, wpm: wpm, accuracy: accuracy, submittedAt: submittedAt } }];
